/** Every known board on these platforms, as { kind, identifier, openRoles, name }. */
export const ATS_BOARDS = BLOB.split('\n').map((line) => {
  const parts = line.split('\t');
  return { kind: parts[0], identifier: parts[1], openRoles: Number(parts[2]) || 0, name: parts[3] };
});
